/**
 * TASK: Swap two int values WITHOUT declaring a temporary variable.
 *
 * The usual swap needs a third variable:
 *     int temp = a; a = b; b = temp;
 * Here you must do it with arithmetic instead:
 *     a = a + b;   // a now holds the total
 *     b = a - b;   // b becomes the old a
 *     a = a - b;   // a becomes the old b
 *
 * swapped(3, 8)  -> {8, 3}
 * swapped(-4, 9) -> {9, -4}
 *
 * swapInPlace changes the array itself:
 *     int[] xs = {10, 20, 30};
 *     swapInPlace(xs, 0, 2);   // xs is now {30, 20, 10}
 *
 * EDGE CASE: swapInPlace(xs, 1, 1) asks a slot to swap with ITSELF, and the
 * arithmetic trick breaks there -- both halves of a + b read the same slot,
 * so the slot doubles and then subtracts itself down to 0. Return early when
 * i == j so the array is left untouched.
 */
public class NoTempSwapper {

    public static int[] swapped(int a, int b) {
        // TODO: swap a and b using only + and -, then return {a, b}
        return new int[] {0, 0};
    }

    public static void swapInPlace(int[] values, int i, int j) {
        // TODO: do nothing when i == j
        // TODO: otherwise swap values[i] and values[j] without a temp variable
    }
}

