import java.util.Arrays;

public class NoTempSwapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(int[] values) {
        return values == null ? "null" : Arrays.toString(values);
    }

    public static void main(String[] args) {
        check("swapped(3, 8)", "[8, 3]", show(NoTempSwapper.swapped(3, 8)));
        check("swapped(-4, 9)", "[9, -4]", show(NoTempSwapper.swapped(-4, 9)));
        check("swapped(7, 7)", "[7, 7]", show(NoTempSwapper.swapped(7, 7)));
        check("swapped(0, 5)", "[5, 0]", show(NoTempSwapper.swapped(0, 5)));

        try {
            int[] xs = {10, 20, 30};
            NoTempSwapper.swapInPlace(xs, 0, 2);
            check("swapInPlace({10,20,30}, 0, 2)", "[30, 20, 10]", show(xs));

            int[] ys = {1, 2, 3, 4};
            NoTempSwapper.swapInPlace(ys, 1, 2);
            check("swapInPlace({1,2,3,4}, 1, 2)", "[1, 3, 2, 4]", show(ys));

            int[] same = {5, 6, 7};
            NoTempSwapper.swapInPlace(same, 1, 1);
            check("swapInPlace(same index) leaves array alone", "[5, 6, 7]", show(same));

            int[] negatives = {-8, 12};
            NoTempSwapper.swapInPlace(negatives, 0, 1);
            check("swapInPlace with negatives", "[12, -8]", show(negatives));
        } catch (RuntimeException ex) {
            System.out.println("FAIL  swapInPlace threw " + ex);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

