public class NoTempSwapper {

    public static int[] swapped(int a, int b) {
        a = a + b;
        b = a - b;
        a = a - b;
        return new int[] {a, b};
    }

    public static void swapInPlace(int[] values, int i, int j) {
        if (i == j) {
            return;
        }
        values[i] = values[i] + values[j];
        values[j] = values[i] - values[j];
        values[i] = values[i] - values[j];
    }
}
